70: fn decision_for_uncertainty(
71:   policy : AcceptancePolicy,
72:   ratio : Double,
73: ) -> QualityDecision? {
74:   if ratio > policy.fail_uncertainty_ratio {
75:     Some(QualityDecision::Fail(reason="uncertainty exceeds policy limit"))
76:   } else if ratio > policy.warning_uncertainty_ratio {
