83: ///|
84: /// Evaluate one observed value and its stated uncertainty.
85: pub fn evaluate_value(
86:   policy~ : AcceptancePolicy,
87:   feature~ : Feature,
88:   value~ : Double,
89:   uncertainty~ : Double,
90: ) -> ValueQualityResult {
91:   let normalized_deviation = relative_error(feature, value)
92:   let tolerance = tolerance_half_width(feature)
93:   let ratio = if tolerance == 0.0 {
94:     if uncertainty == 0.0 {
95:       0.0
96:     } else {
97:       policy.fail_uncertainty_ratio + 1.0
98:     }
99:   } else {
100:     uncertainty.abs() / tolerance
101:   }
102:   let decision = if value < lower_limit(feature) || value > upper_limit(feature) {
103:     QualityDecision::Fail(reason="value outside tolerance")
104:   } else {
105:     match decision_for_uncertainty(policy, ratio) {
106:       Some(decision) => decision
107:       None => QualityDecision::Pass
108:     }
109:   }
110:   { feature_id: feature.id, value, normalized_deviation, uncertainty, decision }
111: }

