71: ///|
72: pub fn Chain::worst_case(self : Chain) -> AnalysisResult {
73:   let mut total = 0.0
74:   let mut span = 0.0
75:   for d in self.dimensions {
76:     total += signed_nominal(d)
77:     span += d.tolerance
78:   }
79:   let sensitivities = self.dimensions.map(d => (d.name, d.tolerance))
80:   {
81:     nominal: total,
82:     lower: total - span,
83:     upper: total + span,
84:     mean: total,
85:     standard_deviation: span,
86:     yield_rate: 1.0,
87:     sensitivity: sensitivities,
88:   }
89: }
