91: ///|
92: pub fn Chain::rss(self : Chain) -> AnalysisResult {
93:   let mut total = 0.0
94:   let mut variance = 0.0
95:   for d in self.dimensions {
96:     total += signed_nominal(d)
97:     variance += d.tolerance * d.tolerance
98:   }
99:   let sigma = variance.sqrt()
100:   let sensitivities = self.dimensions.map(d => {
101:     (d.name, d.tolerance * d.tolerance)
102:   })
103:   {
104:     nominal: total,
105:     lower: total - 3.0 * sigma,
106:     upper: total + 3.0 * sigma,
107:     mean: total,
108:     standard_deviation: sigma,
109:     yield_rate: 0.9973,
110:     sensitivity: sensitivities,
111:   }

