31: ///|
32: /// Combined RSS uncertainty and its named contributors.
33: pub struct UncertaintyBudget {
34:   contributors : Array[UncertaintyContribution]
35:   combined : Double
36:   total_variance : Double
37: } derive(Debug, Eq)
38: 
39: ///|
40: /// Combine independent uncertainty sources by root-sum-square propagation.
41: pub fn uncertainty_budget(
42:   sources : Array[UncertaintySource],
43: ) -> UncertaintyBudget {
44:   if sources.length() == 0 {
45:     abort("uncertainty budget must contain at least one source")
46:   }
47:   let effective = sources.map(source => {
48:     source.standard_uncertainty * source.sensitivity
49:   })
50:   let mut total_variance = 0.0
51:   for value in effective {
52:     total_variance += value * value
53:   }
54:   let combined = total_variance.sqrt()
55:   let contributors = sources.map(source => {
56:     let value = source.standard_uncertainty * source.sensitivity
57:     let variance = value * value
58:     let fraction = if total_variance == 0.0 {
59:       0.0
60:     } else {
61:       variance / total_variance
62:     }
63:     { name: source.name, effective_uncertainty: value, variance, fraction }
64:   })
65:   { contributors, combined, total_variance }
66: }
67: 
68: ///|
69: /// Return a symmetric interval at a requested coverage multiplier.
70: pub fn UncertaintyBudget::interval(
71:   self : UncertaintyBudget,
72:   nominal : Double,
73:   coverage_factor : Double,
74: ) -> Interval {
75:   if coverage_factor < 0.0 {
76:     abort("uncertainty coverage factor must be non-negative")
77:   }
78:   let margin = self.combined * coverage_factor
79:   Interval::new(nominal - margin, nominal + margin)
80: }

