96: ///|
97: /// Return contributors ordered by variance fraction.
98: pub fn UncertaintyBudget::ranked(
99:   self : UncertaintyBudget,
100: ) -> Array[UncertaintyContribution] {
101:   let result = self.contributors
102:   for index in 1..<result.length() {
103:     let current = result[index]
104:     let mut position = index
105:     while position > 0 && result[position - 1].fraction < current.fraction {
106:       result[position] = result[position - 1]
107:       position -= 1
108:     }
109:     result[position] = current
110:   }
111:   result
112: }
