114: ///|
115: /// Calculate the reduction in combined uncertainty after removing a source.
116: pub fn uncertainty_without(
117:   budget : UncertaintyBudget,
118:   source_name : String,
119: ) -> Double {
120:   let mut remaining_variance = budget.total_variance
121:   for contributor in budget.contributors {
122:     if contributor.name == source_name {
123:       remaining_variance -= contributor.variance
124:     }
125:   }
126:   if remaining_variance <= 0.0 {
127:     0.0
128:   } else {
129:     remaining_variance.sqrt()
130:   }

700: /// Estimate a linear clock correction from paired local and reference times.
701: pub fn fit_sensor_clock(
702:   local_timestamps : Array[Int],
703:   reference_timestamps : Array[Int],
704: ) -> SensorClockFit {
705:   let count = if local_timestamps.length() < reference_timestamps.length() {
706:     local_timestamps.length()
707:   } else {
708:     reference_timestamps.length()
709:   }
710:   if count == 0 {
711:     return {
712:       offset: 0.0,
713:       drift: 0.0,
714:       reference: 0,
715:       residual_rms: 0.0,
716:       samples: 0,
717:       valid: false,
718:     }
719:   }
720:   let reference = local_timestamps[0]
721:   let mut sx = 0.0
722:   let mut sy = 0.0
723:   let mut sxx = 0.0
724:   let mut sxy = 0.0
725:   for i in 0..<count {
726:     let x = (local_timestamps[i] - reference).to_double()
727:     let y = (reference_timestamps[i] - local_timestamps[i]).to_double()
728:     sx = sx + x
729:     sy = sy + y
730:     sxx = sxx + x * x
731:     sxy = sxy + x * y
732:   }
733:   let denominator = count.to_double() * sxx - sx * sx
734:   let drift = if denominator.abs() <= 0.000000000001 {
735:     0.0
736:   } else {
737:     (count.to_double() * sxy - sx * sy) / denominator
738:   }
739:   let offset = (sy - drift * sx) / count.to_double()
740:   let mut square_error = 0.0
741:   for i in 0..<count {
742:     let x = (local_timestamps[i] - reference).to_double()
743:     let observed = (reference_timestamps[i] - local_timestamps[i]).to_double()
744:     let error = observed - offset - drift * x
745:     square_error = square_error + error * error
746:   }
747:   {
748:     offset,
749:     drift,
750:     reference,
751:     residual_rms: (square_error / count.to_double()).sqrt(),
752:     samples: count,
753:     valid: count >= 2,
754:   }

58: ///|
59: /// Rich SNTP analysis. A small negative measured network delay is clamped to
60: /// zero, as in beevik/ntp; strict measure() retains its existing rejection.
61: pub fn analyze(
62:   sent : Timestamp,
63:   reply : Packet,
64:   arrived : Timestamp,
65:   pivot_unix : Double,
66: ) -> ResponseInfo raise NtpError {
67:   if reply.version < 2 || reply.version > 4 || reply.mode != 4 {
68:     raise Invalid("not an NTPv2/v3/v4 server response")
69:   }
70:   if reply.origin != sent {
71:     raise Invalid("origin mismatch")
72:   }
73:   if reply.receive == Timestamp::zero() || reply.transmit == Timestamp::zero() {
74:     raise Invalid("missing server timestamp")
75:   }
76:   let elapsed = arrived.difference(sent)
77:   let processing = reply.transmit.difference(reply.receive)
78:   if elapsed < 0.0 ||
79:     elapsed > 86400.0 ||
80:     processing < 0.0 ||
81:     processing > 86400.0 {
82:     raise Invalid("invalid time ordering or excessive interval")
83:   }
84:   let a = reply.receive.difference(sent)
85:   let b = reply.transmit.difference(arrived)
86:   let sample : Sample = {
87:     offset_seconds: a / 2.0 + b / 2.0,
88:     delay_seconds: (elapsed - processing).max(0.0),
89:   }
90:   {
91:     sample,
92:     minimum_error_seconds: (-a).max(b).max(0.0),
93:     server_transmit_unix: reply.transmit.near_unix(pivot_unix),
94:     reference_unix: reply.reference.near_unix(pivot_unix),
95:     precision_seconds: @math.pow(2.0, reply.precision.to_double()),
96:     poll_seconds: @math.pow(2.0, reply.poll.to_double()),
97:     root_distance_seconds: reply.root_distance(sample),
98:     reference_string: reply.reference_string(),
99:   }
100: }

18: ///|
19: /// Check synchronization health in addition to measure's request/time validation.
20: /// Freshness and peer-distance limits follow beevik/ntp's Validate defaults.
21: pub fn Packet::validate_health(self : Packet) -> Unit raise NtpError {
22:   if self.version < 2 || self.version > 4 || self.mode != 4 {
23:     raise Invalid("not an NTPv2/v3/v4 server response")
24:   }
25:   if self.stratum < 1 || self.stratum > 15 || self.leap < 0 || self.leap > 2 {
26:     raise Invalid("unsynchronized or kiss-of-death response")
27:   }
28:   if self.reference == Timestamp::zero() || self.transmit == Timestamp::zero() {
29:     raise Invalid("missing reference or transmit timestamp")
30:   }
31:   let age = self.transmit.difference(self.reference)
32:   if age < 0.0 {
33:     raise Invalid("reference timestamp follows transmit timestamp")
34:   }
35:   if age > 131072.0 {
36:     raise Invalid("stale server reference timestamp")
37:   }
38:   let distance = self.root_delay.to_double().max(0.0) / 131072.0 +
39:     self.root_dispersion.to_double() / 65536.0
40:   if distance > 16.0 {
41:     raise Invalid("excessive root synchronization distance")
42:   }
43: }
