67: ) -> ExactRational {
68:   guard radix > 1 else { abort("semantic radix must be greater than one") }
69:   if exponent >= 0 {
70:     ExactRational::new(significand * pow_bigint(radix, exponent), 1N)
71:   } else {
72:     ExactRational::new(significand, pow_bigint(radix, -exponent))
73:   }
74: }

95: ///|
96: pub fn SemanticScalar::from_bin_float(
97:   x : @bin_float.BinFloat,
98: ) -> SemanticScalar {
99:   match x.classify() {
100:     @lf_arith.FpClass::Finite => {
101:       let magnitude = BigInt::from_octets(x.coefficient().to_bytes_be())
102:       let signed = if x.is_negative() { -magnitude } else { magnitude }
103:       Rational(ExactRational::from_scaled_integer(signed, 2, x.exponent2()))
104:     }
105:     @lf_arith.FpClass::Infinity => Infinity(x.sign())
106:     @lf_arith.FpClass::NaN => NaN
107:   }
108: }
