111: pub fn SemanticScalar::from_decimal(x : @decimal.Decimal) -> SemanticScalar {
112:   match x.classify() {
113:     @lf_arith.FpClass::Finite =>
114:       Rational(
115:         ExactRational::from_scaled_integer(x.coefficient(), 10, x.exponent10()),
116:       )
117:     @lf_arith.FpClass::Infinity => Infinity(x.sign())
118:     @lf_arith.FpClass::NaN => NaN
119:   }
120: }

1: ///|
2: /// Machine-readable output: one JSON object per report, on one line.
3: ///
4: /// Line-delimited rather than a single array, so a tool can stream results and
5: /// a build that dies half way still leaves valid records behind.
6: ///
7: /// Positions are given twice on purpose. `offset`/`length` are the UTF-16 code
8: /// units this library works in; `line`/`column` are 1-based and 0-based
9: /// respectively, in code points, which is what a human-facing tool wants. A
10: /// consumer that needs one should not have to reconstruct it from the other,
11: /// because reconstructing it requires the source text and the whole point of
12: /// the JSON is to be usable without it.
13: pub fn json(
14:   report : @report.Report,
15:   cache : &@report.SourceCache,
16:   buf : StringBuilder,
17: ) -> Unit {
18:   buf.write_string(report_json(report, cache).stringify())
19:   buf.write_char('\n')
20: }
21: 
22: ///|
23: /// The JSON value for one report, related diagnostics nested inside it.
24: pub fn report_json(
25:   report : @report.Report,
26:   cache : &@report.SourceCache,
27: ) -> Json {
28:   let obj : Map[String, Json] = Map([])
29:   obj["severity"] = Json::string(report.severity.name())
30:   match report.code {
31:     Some(code) => obj["code"] = Json::string(code)
32:     None => ()
33:   }
34:   obj["message"] = Json::string(report.message)
35:   if report.labels.length() > 0 {
36:     obj["labels"] = Json::array(report.labels.map(l => label_json(l, cache)))
37:   }
38:   if report.notes.length() > 0 {
39:     obj["notes"] = Json::array(report.notes.map(n => Json::string(n)))
40:   }
41:   match report.help {
42:     Some(h) => obj["help"] = Json::string(h)
43:     None => ()
44:   }
45:   match report.url {
46:     Some(u) => obj["url"] = Json::string(u)
47:     None => ()
48:   }
49:   if report.fixes.length() > 0 {
50:     obj["fixes"] = Json::array(report.fixes.map(f => fix_json(f, cache)))
51:   }
52:   if report.related.length() > 0 {
53:     obj["related"] = Json::array(report.related.map(r => report_json(r, cache)))
54:   }
55:   Json::object(obj)
56: }
57: 
58: ///|
59: fn label_json(label : @report.Label, cache : &@report.SourceCache) -> Json {
60:   let obj : Map[String, Json] = Map([])
61:   obj["style"] = Json::string(
62:     match label.style {
63:       Primary => "primary"
64:       Secondary => "secondary"
65:     },
66:   )
67:   obj["offset"] = Json::number(label.span.start.to_double())
68:   obj["length"] = Json::number(label.span.len.to_double())
69:   add_position(obj, label.source, label.span, cache)
70:   match label.message {
71:     Some(m) => obj["message"] = Json::string(m)
72:     None => ()
73:   }
74:   Json::object(obj)
75: }

